async function scan09(type){const barcode=type==='barcode',m=sheet09(barcode?'Scan a barcode':type==='photo'?'Estimate a meal':'Scan a nutrition label',`<p>${barcode?'Upload a barcode image, or type its digits. Product information must be verified before logging.':type==='photo'?'Meal estimates need a configured vision provider and are always estimates.':'Upload a clear, straight-on label photo. Extraction needs a configured vision provider. You will review every value before saving.'}</p>${barcode?'<label>Barcode digits<input class="field" id="barcode09" inputmode="numeric" pattern="[0-9]{8,14}" placeholder="UPC / EAN"></label>':''}<label class="upload09">${barcode?'Choose barcode image':'Take or upload photo'}<input type="file" id="scanFile09" accept="image/*" capture="environment"></label><img id="scanPreview09" alt="Uploaded image for review" hidden><p role="status" id="scanStatus09"></p><div class="inline09"><button class="primary" id="scanGo09">${barcode?'Look up product':'Extract & review'}</button><button class="secondary" id="scanManual09">Enter manually</button></div>`);let dataURL=null;m.querySelector('#scanFile09').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>6*1024*1024){m.querySelector('#scanStatus09').textContent='Choose an image smaller than 6 MB.';return;}dataURL=await new Promise(resolve=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.readAsDataURL(file);});const img=m.querySelector('img');img.src=dataURL;img.hidden=false;if(barcode){try{if(!('BarcodeDetector' in window))throw Error();const detector=new BarcodeDetector({formats:['ean_13','ean_8','upc_a','upc_e']}),bitmap=await createImageBitmap(file),codes=await detector.detect(bitmap);bitmap.close();if(!codes.length)throw Error();m.querySelector('#barcode09').value=codes[0].rawValue;}catch{m.querySelector('#scanStatus09').textContent='Automatic detection is unavailable or could not read this image. Enter the printed digits.';}}};m.querySelector('#scanManual09').onclick=()=>{m.close();food09();};m.querySelector('#scanGo09').onclick=async()=>{const status=m.querySelector('#scanStatus09'),b=m.querySelector('#scanGo09');b.disabled=true;status.textContent='Checking…';try{let product;if(barcode){const code=m.querySelector('#barcode09').value.trim();if(!/^\d{8,14}$/.test(code))throw Error('Enter 8–14 barcode digits.');const res=await fetch('/api/barcode/'+code);const d=await res.json();if(!res.ok)throw Error(d.error||'Product lookup unavailable.');product=d.food;}else{if(!dataURL)throw Error('Choose an image first.');const res=await fetch('/api/vision',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({image:dataURL,mode:type})});const d=await res.json();if(!res.ok)throw Error(d.error||'Image extraction is unavailable.');product=d.food;}if(!product)throw Error('No reliable nutrition returned. Enter the label manually.');m.close();food09(product,type==='photo'?'AI estimate — verify portions':barcode?'Open Food Facts — verify label':'Label extraction — verify all fields');}catch(e){status.textContent=e instanceof SyntaxError?'Scanning requires the IXHUA server. Manual entry is available.':e.message;}finally{b.disabled=false;}};}
