function ai09(origin,detail=null){const athlete=state.athlete,role=athlete?.primary,roleQuestions={runner:['Explain my next run','How does my running baseline shape this week?','What strength supports my running?'],strength:['Explain my lifting split','Which muscle groups are prioritized?','When should I increase my load?'],hybrid:['How are my running and lifting priorities balanced?','Which session should I protect this week?','Explain the spacing of my hard sessions'],general:['How does this week balance strength and aerobic fitness?','How can I stay consistent?','Review my completed week'],longevity:['How does this plan use my capability baseline?','Explain my balance practice','Review my completed week'],custom:['Explain my leading training quality','How do my selected qualities fit together?','Review my completed week']};const m=sheet09('Ask IXHUA',`<div class="label">ASK IXHUA / ${esc(origin)}</div><p>${athlete?esc((window.IXHUA_ONBOARDING?.identities.find(x=>x[0]===role)?.[1]||role)+' context: your actual goals, plan, equipment and logged history. '):''}Recommendations are separate from recorded results.</p><div class="ai-quick09">${(origin==='nutrition'?['How much protein remains?','Analyze today’s macros','What should I eat next?']:origin==='exercise'?['Explain technique','Explain my progression','Why this movement?']:roleQuestions[role]||['Analyze my progress','What should I improve?','Compare my sessions']).map(q=>`<button class="secondary" data-q09="${q}">${q}</button>`).join('')}</div><div class="ai-output09" id="aiOutput09" aria-live="polite">No answer yet. Your relevant IXHUA data will be sent when you ask.</div><form id="aiForm09" class="chat-row"><input class="field" id="aiQuestion09" aria-label="Question for IXHUA" maxlength="1500" required placeholder="Ask about your next step…"><button class="primary">Ask ↗</button></form><p class="tiny-note">Live AI requires a server-side provider key. No simulated answers.</p>`);const input=m.querySelector('input');m.querySelectorAll('[data-q09]').forEach(b=>b.onclick=()=>{input.value=b.dataset.q09;m.querySelector('form').requestSubmit();});m.querySelector('form').onsubmit=async e=>{e.preventDefault();const q=input.value.trim();if(!q)return;const out=m.querySelector('#aiOutput09'),btn=m.querySelector('form button');btn.disabled=true;out.textContent='Reviewing your logged context…';try{const res=await fetch('/api/coach',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:q,context:context09(origin,detail)})});const data=await res.json();if(!res.ok)throw Error(data.error||'IXHUA AI is unavailable.');if(typeof data.answer!=='string')throw Error('No answer returned. Try again.');out.textContent=data.answer;state.aiHistory.push({origin,question:q,answer:data.answer,at:Date.now()});state.aiHistory=state.aiHistory.slice(-50);save();}catch(e){out.textContent=e instanceof SyntaxError?'AI is unavailable in static hosting. Start the IXHUA server and configure the provider.':e.message;}finally{btn.disabled=false;}};}
