function restDock09(){let dock=document.getElementById('restDock09');if(!live09()?.rest){dock?.remove();return;}if(!dock){dock=document.createElement('div');dock.id='restDock09';document.body.append(dock);}const t=live09().rest;dock.innerHTML=`<div><span class="label">REST ${t.paused?'PAUSED':''}</span><b id="restTime09">${fmtTimer(t.paused?t.remaining:Math.max(0,Math.ceil((t.endsAt-Date.now())/1000)))}</b></div><button data-rest09="-15" aria-label="Subtract 15 seconds">−15</button><button data-rest09="toggle">${t.paused?'Resume':'Pause'}</button><button data-rest09="15" aria-label="Add 15 seconds">+15</button><button data-rest09="reset">Reset</button><button data-rest09="close" aria-label="Dismiss rest timer">×</button>`;dock.querySelectorAll('[data-rest09]').forEach(b=>b.onclick=()=>{const t=live09()?.rest;if(!t)return;const a=b.dataset.rest09,rem=t.paused?t.remaining:Math.max(0,Math.ceil((t.endsAt-Date.now())/1000));if(a==='close'){live09().rest=null;}else if(a==='toggle'){t.paused=!t.paused;t.remaining=rem;t.endsAt=Date.now()+rem*1000;}else if(a==='reset'){t.paused=true;t.remaining=t.duration;}else{t.remaining=Math.max(0,rem+(+a));t.endsAt=Date.now()+t.remaining*1000;}save();restDock09();});}
setInterval(()=>{const s=live09();if(!s)return;const elapsed=document.getElementById('elapsed09');if(elapsed)elapsed.textContent=fmtTimer(elapsed09(s));const t=s.rest,out=document.getElementById('restTime09');if(t&&!t.paused&&out){const rem=Math.max(0,Math.ceil((t.endsAt-Date.now())/1000));out.textContent=fmtTimer(rem);if(!rem){s.rest=null;save();restDock09();notify09('Rest complete. Ready for your next set.');}}},500);
